TP.register({id:"lp9-g1",lp:9,grade:"1",mode:"baseline",nextGrade:"2nd grade",build(E){const F=E.F;const TENT="tent",CANOE="canoe",PINE="pine",FIRE="fire",FISH="fish",FROG="frog",DEER="deer",OWL="owl",DUCK="duck",SQUIRREL="squirrel",ACORN="acorn",PACK="pack",BOOT="boot",HAT="topHat",MAP="map",TORCH="torch",PAN="pan",SOUP="soup",SUN="sun",BOOK="books",MOUNTAIN="mountain",EAR="ear",BIRD="bluebird";const ic=(e,px)=>(F.icon||F.pic2)(e,px)||e;const K_EYE=window.TP_ICON_EYE||((x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`);const K_BLUSH=window.TP_ICON_BLUSH||((x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`);const K_SMILE=window.TP_ICON_SMILE||((x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`);const K_FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>K_EYE(cx-sp,cy)+K_EYE(cx+sp,cy)+K_BLUSH(cx-sp-7,cy+9)+K_BLUSH(cx+sp+7,cy+9)+K_SMILE(cx,cy+9,mw||4));const n1=v=>Math.round(v*10)/10;const at=(x,y,k,inner)=>`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(k)})">${inner}</g>`;const INK="#6B4A3C",LOGC="#C9875A",LOGEND="#E0B07A",LOGLN="#A8724E",SKY="#CDEAF4",GRASS="#BCDCA4",GRASS_LN="#93BC7C",LAKE="#6FB6C8",LAKE_LN="#4E94A6",FOAM="#DCF2F6",DOCK="#D9A066",DOCK_D="#C08A5E",TRUNK="#A8724E",PINE_A="#8CC79A",PINE_B="#6FB183";function logShape(x,y,w,rot){const k=w/58;return`<g transform="translate(${n1(x)} ${n1(y)}) rotate(${rot||0}) scale(${n1(k)})"><rect x="-26" y="-9" width="52" height="18" rx="9" fill="${LOGC}" stroke="${INK}" stroke-width="3"/><ellipse cx="-26" cy="0" rx="5.5" ry="9" fill="${LOGEND}" stroke="${INK}" stroke-width="2.6"/><path d="M4 -4 h15 M2 4 h12" fill="none" stroke="${LOGLN}" stroke-width="2.4" stroke-linecap="round"/></g>`}const logSvg=w=>`<svg viewBox="0 0 ${w} ${Math.round(w*.46)}" width="${w}" style="vertical-align:middle" role="img" aria-label="a cut log">${logShape(w*.5,w*.23,w*.92)}</svg>`;const MORNING="The lake is flat and still when I wake up. I pull on my boots. I walk down to the dock. No one else is up. Mist sits on the water. It looks like a soft blanket. I count seven ducks. They swim near the reeds. A fish jumps once. The rings spread out wide. Then I hear the pan rattle. It is up at camp. I turn and run back for breakfast.";const PADDLE="Teo made a paddle in the camp workshop. He cut a flat board for the blade and added a long handle. He sanded the edges until they were smooth. Then he carried the paddle down to the dock. But the handle was too long, and his hands were too far apart to hold it well. Luz held the paddle up against him and marked the spot with a pencil. The camp leader got a saw and cut the end off at the mark. Then Teo climbed into the canoe and pushed off. The paddle fit him just right.";const PINES="Most trees drop all their leaves when the cold comes. A pine tree does not. Its leaves are thin, hard needles, and each needle has a waxy coat. The coat keeps the water inside. Because of that, a needle can stay on the branch for two years or more. A pine tree lets only a few needles go at a time, so it is never bare. That is why a pine tree looks green in every season.";const DUGOUT="Long before anyone had a factory, people made a canoe out of a single tree. They picked a big straight log and hollowed out the middle, a little at a time, until the walls were thin and even. A boat made this way is called a dugout. A dugout is heavy, but it is strong, and one log can make a boat that carries four or five people. Some dugouts lasted for more than thirty years.";const CREW="The trail crew starts work before the sun is high. They carry saws and shovels up the ridge and clear the brush that grew in over the winter. Where the path crosses a wet spot they lay flat stones, one at a time, until a walker can step across without sinking. By the end of a long day the crew has opened about half a mile of trail.";const WORDS=["chip","bunk","float","grill","pine","high","creek","start","packed","campfire","otter","blape"];function story(title,text){return`<p class="big" style="text-align:center;margin:0 0 6px">${title}</p><p class="passage">${text}</p>`}function lab(x,y,t,sz,c){return`<text x="${x}" y="${y}" font-size="${sz||22}" font-family="Andika,sans-serif" font-weight="700" fill="${c||"var(--ink)"}" text-anchor="middle">${t}</text>`}function logGrid(n,per){const cell=96,rows=Math.ceil(n/per),w=per*cell+24,h=rows*58+28;let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;for(let i=0;i<n;i++)b+=logShape(12+i%per*cell+cell/2,20+Math.floor(i/per)*58+22,78);return`<svg viewBox="0 0 ${w} ${h}" width="${Math.min(w,620)}" role="img" aria-label="${n} cut logs">${b}</svg>`}function unitFig(){const u=52,y1=54,y2=182,W=460,H=244;let s=`<svg viewBox="0 0 ${W} ${H}" width="440" role="img" aria-label="A canoe paddle above six blocks laid end to end, and a log above four blocks laid end to end.">`;s+=`<rect x="3" y="3" width="${W-6}" height="${H-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;s+=`<path d="M40 ${y1-10} h${6*u-26}" stroke="${DOCK}" stroke-width="10" stroke-linecap="round" fill="none"/>`;s+=`<ellipse cx="${40+6*u-14}" cy="${y1-10}" rx="16" ry="11" fill="${LOGEND}" stroke="${INK}" stroke-width="2.8"/>`;for(let i=0;i<6;i++)s+=`<rect x="${40+i*u}" y="${y1}" width="${u}" height="28" fill="#FBD873" stroke="${INK}" stroke-width="2.5"/>`;s+=lab(396,y1+22,"paddle",22);s+=logShape(40+2*u+8,y2-36,4*u);for(let i=0;i<4;i++)s+=`<rect x="${40+i*u}" y="${y2}" width="${u}" height="28" fill="#FBD873" stroke="${INK}" stroke-width="2.5"/>`;s+=lab(300,y2+22,"log",22);s+=`<text x="${W-20}" y="26" font-size="19" text-anchor="end" font-family="Andika,sans-serif" font-weight="700" fill="var(--muted)">Every block is the same size.</text>`;return s+"</svg>"}function packList(){return F.table(["What we take","What it is for"],[[`${ic(TORCH,30)} a flashlight`,"to see the trail after the sun goes down"],[`${ic(MAP,30)} a trail map`,"to find the way back to camp"],[`${ic(PAN,30)} a small pan`,"to cook over the fire ring"],[`${ic(HAT,30)} a hat`,"to keep the sun off your face"]],{caption:"Lookout Hike Pack List"})}function sharesFig(){const st=`stroke="${INK}" stroke-width="3.4" stroke-linejoin="round"`;const W=720,H=240;let b=`<rect x="3" y="3" width="${W-6}" height="${H-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;b+=`<circle cx="120" cy="108" r="72" fill="#F6C97A" ${st}/><path d="M120 36 V180" ${st} fill="none"/>`;b+=lab(120,214,"Shape A",24);b+=`<rect x="288" y="36" width="144" height="144" rx="8" fill="#A8D8E8" ${st}/><path d="M360 36 V180 M288 108 H432" ${st} fill="none"/>`;b+=lab(360,214,"Shape B",24);b+=`<circle cx="600" cy="108" r="72" fill="#C7E3A8" ${st}/><path d="M558 50 L558 166" ${st} fill="none"/>`;b+=lab(600,214,"Shape C",24);return`<svg viewBox="0 0 ${W} ${H}" width="700" role="img" aria-label="Shape A is a circle cut by one line down the middle into two equal parts. Shape B is a square cut by two lines into four equal parts. Shape C is a circle cut by one off-center line into two parts that are not the same size.">${b}</svg>`}const CLOCKS=[["A",3,0],["B",7,30],["C",11,0],["D",1,30]];function clockRow(){return`<div class="figure" style="gap:18px;flex-wrap:wrap;justify-content:center">`+CLOCKS.map(c=>`<div>${F.clock(c[1],c[2],200)}<p class="fig-label">Clock ${c[0]}</p></div>`).join("")+`</div>`}const TWO=`<ul class="qlist" style="margin-top:14px"><li>Write 2 or 3 sentences.</li></ul>`;const WDIR="Write on your paper. When you finish, hold it up and read it to your teacher.";const STOPS=[{id:1,title:"Lake Sound Check",short:"Sounds",parts:[{std:["RF.1.2"],n:6,dur:55,dir:"Listen to your teacher. Say the sounds and words out loud.",html:()=>`<p class="huge" aria-hidden="true">${ic(EAR,96)} ${ic(FISH,96)}</p><p class="big" style="text-align:center">Listen. Then say it.</p>`,key:["Blend these sounds: /d/ /o/ /k/ (dock)","Blend these sounds: /p/ /ie/ /n/ (pine)","Clap the word parts in canoe. How many parts? (2 parts: ca and noe)","What is the last sound in camp? (/p/)","Say all the sounds in log. (/l/ /o/ /g/, three sounds)","Which word has a long vowel sound: lake or lap? (lake)"],desc:"blending, segmenting, and isolating sounds, counting syllables, and telling long from short vowels in spoken words"}]},{id:2,title:"Camp Words",short:"Words",parts:[{std:["RF.1.3"],kind:"words",words:WORDS,n:12,dur:75,dir:"Read each word out loud. The last one is a silly word. Just sound it out.",key:["Count each word read correctly. blape is a silly word: listen for the long a that the final e makes.","Watch for: ch digraph (chip), nk ending (bunk), blend plus a vowel team (float), blend plus double letters (grill), final e (pine), igh (high), blend plus ee team (creek), blend plus r-controlled ar (start), the -ed ending said as /t/ (packed), a compound word (campfire), two syllables with r-controlled er (otter)."],desc:"reading words with digraphs, blends, final e, vowel teams, r-controlled vowels, endings, and two syllables"}]},{id:3,title:"Count the Woodpile",short:"To 120",parts:[{std:["1.NBT.A.1"],n:4,dur:65,dir:"Count and read out loud. Write your numbers on your paper and hold it up.",html:()=>`<p class="small" style="text-align:center">The camp counts every log before it goes on the rack.</p>`,qs:["Count out loud from 95 to 112.","Read these numbers out loud: 73, 106, 119.","Write the number one hundred eight.","Count the logs in the picture. Write the number that tells how many."],fig2:()=>F.row(logGrid(14,7)),key:["95, 96, 97, 98, 99, 100, 101 ... 112. Watch the jump past 99","Seventy-three, one hundred six, one hundred nineteen","108, not 1008","14"],desc:"counting, reading, and writing numerals to 120 and counting objects"}]},{id:4,title:"Morning on the Lake",short:"Lake Read",parts:[{std:["RF.1.4"],kind:"read",n:70,label:"words read correctly",dur:85,dir:"Look at the three pictures. Then read the story out loud in your best reading voice.",html:()=>`${F.row(F.pic(DUCK,"ducks on the water","3.6rem"),F.pic(PAN,"the camp pan","3.6rem"),F.pic(BOOT,"your boots","3.6rem"))}${story("Morning on the Lake",MORNING)}`,key:["70 words, not counting the title. Mark each word read wrong or skipped. A word the student fixes alone counts as correct.","Point to the three pictures first so ducks, pan, and boots are clear before the student reads.","Note pace, expression, and whether the student rereads to fix a mistake.","Quick check after reading: What sends the reader back to camp? (the sound of the pan rattling, which means breakfast)"],desc:"a 70-word lake camp story read aloud"}]},{id:5,title:"Log Hops and Smart Adding",short:"Hops",parts:[{title:"Log Hops",std:["1.OA.C.5"],n:5,dur:70,dir:"Count out loud like you are hopping from log to log. Say each answer.",html:()=>`<p class="big" style="text-align:center">There is nothing on the screen. You cannot count it. Every hop is one number you say out loud.</p>`,qs:["Start at 9. Count on 5. Where do you land? What adding sentence is that?","Start at 16. Count back 4. Where do you land? What take away sentence is that?","Solve 2 + 8 by counting on. Which number is faster to start at? Say the numbers you count.","Solve 13 - 10. Start at 10 and count up to 13. How many hops is that?","True or silly? To solve 11 - 2, Dev counts 11, 10 and says the answer is 10."],key:["Counts 10, 11, 12, 13, 14. Lands on 14. 9 + 5 = 14","Counts 15, 14, 13, 12. Lands on 12. 16 - 4 = 12","Starts at 8. Counts 9, 10. Answer 10","Counts 11, 12, 13. That is 3 hops, so 13 - 10 = 3","Silly. The first number is not a hop. Count back two hops: 10, 9. The answer is 9"],desc:"counting on and counting back or up to add and subtract"},{title:"Smart Adding",std:["1.OA.B.3"],n:5,dur:85,dir:"Answer out loud. Tell how you know.",html:()=>`<div class="figure" aria-hidden="true">${logSvg(120)}</div><p class="small" style="text-align:center">Nothing here to count. Every number you need is in the question.</p>`,qs:["7 + 8 = 15. So what is 8 + 7?","Luz says 5 + 9 is easier if she turns it around and thinks 9 + 5. Is that OK? What is the total?","Add 4 + 6 + 7. Which two numbers would you add first? Why?","Add 8 + 2 + 5.","Make a ten to solve 8 + 7. Break the 7 into 2 and 5."],key:["15. Knows it without counting because the two numbers just switch places","Yes, that is fine. The order does not change the total. Both make 14","17. Adds 4 + 6 to make 10, then 10 + 7","15. Adds 8 + 2 to make 10, then 10 + 5","15. 8 + 2 = 10, then 10 + 5 = 15"],desc:"using turn-around facts and making ten as strategies to add"}]},{id:6,title:"Camp Problems",short:"Problems",parts:[{std:["1.OA.A.1"],n:5,dur:100,dir:"Listen to each story problem. You can draw on your paper. Say your answer.",html:()=>`<p class="big" style="text-align:center">Listen to each problem. There is nothing to count on the screen, so use your paper.</p>`,qs:["The woodpile had 7 logs. Teo carried up 6 more. How many logs are there now?","16 frogs sat on the bank. Then 7 of them hopped into the water. How many frogs are still on the bank?","Omar counted 8 birds. Dev counted 14 birds. How many more birds did Dev count?","There are 19 logs on the rack. 9 of them are split. The rest are whole. How many are whole?","Some logs were on the rack. Then 6 more went on. Now there are 14. How many were on the rack at the start? Write a number sentence with a box and hold it up."],key:["13 logs (7 + 6 = 13)","9 frogs (16 - 7 = 9)","6 more birds (14 - 8 = 6 or 8 + 6 = 14)","10 whole (19 - 9 = 10 or 9 + 10 = 19)","8 logs. Writes a box plus 6 equals 14, or 14 - 6 equals a box"],desc:"addition and subtraction word problems within 20, with the unknown in different places"}]},{id:7,title:"Teo's Paddle",short:"Teo",parts:[{std:["RL.1.1"],n:5,dur:70,dir:"Read the story out loud. Then listen to each question and answer out loud.",html:()=>`<div class="figure" aria-hidden="true">${ic(CANOE,72)}</div>${story("Teo's Paddle",PADDLE)}`,qs:["What did Teo make?","What was it made of?","What was the problem at the dock?","Who helped Teo, and how?","Ask me a question about the story."],key:["A paddle","A flat board and a long handle","The handle was too long for him to hold with both hands","Luz held the paddle against him and marked the spot with a pencil, and the camp leader sawed the end off at the mark. Naming either helper and what that person did counts.","Asks a real question about the story, such as: Why did he sand the edges? If stuck, say: Start with who, what, or where."],desc:"asking and answering key detail questions about a story the student read"}]},{id:8,title:"Bundles of Ten",short:"Tens Ones",parts:[{std:["1.NBT.B.2"],n:5,dur:75,dir:"Look at the blocks. Answer out loud.",html:()=>`<p class="small" style="text-align:center">A full bundle holds 10 logs. A long block stands for one full bundle of ten, and a small cube stands for one loose log.</p>`,fig:()=>F.row(F.tens(4,2)),qs:["Look at the picture. How many full bundles of ten do you see, and how many loose logs? What number is that?","In the number 18, what does the 1 stand for? What does the 8 stand for?","The camp has 70 logs. How many full bundles of ten is that? How many loose logs are left over?","Which is more, 5 bundles of ten or 40 logs? How do you know?","The number 16 is one ten and six ones. Say a number that is one ten and three ones."],key:["4 bundles of ten and 2 loose. That is 42","The 1 stands for one ten, which is ten logs. The 8 stands for eight ones","7 bundles of ten, and 0 loose logs left over","5 bundles of ten. 5 tens is 50, and 50 is more than 40","13"],desc:"place value in two-digit numbers (bundles of ten and leftover ones)"}]},{id:9,title:"Add and Take Tens",short:"Add Tens",parts:[{title:"Add Up the Camp",std:["1.NBT.C.4"],n:5,dur:75,dir:"Solve each one on your paper. Say your answer and tell how you got it.",html:()=>`<p class="big" style="margin-top:0">The crew counts the logs rack by rack.</p>`,qs:["The first rack holds 34 logs. The crew adds 5 more. How many now?","The second rack holds 52 logs. The crew adds 30 more. How many now?","The third rack holds 47 logs. The crew adds 8 more. How many now?","The fourth rack holds 61 logs. The crew adds 20 more. How many now?","The shed holds 76 logs. The crew adds 9 more. How many now?"],key:["39 (34 + 5 = 39. Only the ones change)","82 (52 + 30 = 82. Adding tens to tens: 5 tens and 3 tens is 8 tens)","55 (47 + 8 = 55. 7 + 8 is 15, so a new ten is made)","81 (61 + 20 = 81)","85 (76 + 9 = 85. 6 + 9 is 15, so a new ten is made)"],desc:"adding within 100 (a two-digit number plus a one-digit number and plus a multiple of ten)"},{title:"Take Away Tens",std:["1.NBT.C.6"],n:5,dur:60,dir:"Answer out loud. For the last one, tell how you know.",html:()=>`<p class="big" style="margin-top:0">Every bundle that comes off the rack takes ten logs away.</p>`,fig:()=>F.row(F.tens(8,0)),qs:["There are 80 logs on the rack. Three bundles of ten come off. 80 - 30 is what?","50 - 40","90 - 60","70 - 20","60 - 10. Tell me how you know, using the word tens."],key:["50 (8 tens take away 3 tens is 5 tens)","10","30","50","50. Looks for: 6 tens take away 1 ten is 5 tens, which is 50"],desc:"subtracting multiples of ten from multiples of ten within 100"}]},{id:10,title:"Measure the Paddle",short:"Measure",parts:[{std:["1.MD.A.2"],n:5,dur:70,dir:"Look at the blocks under the paddle and the log. Answer out loud.",fig:()=>F.row(unitFig()),qs:["How many blocks long is the paddle?","How many blocks long is the log?","Which is longer, the paddle or the log? How many blocks longer?","Why do the blocks have to touch, with no gaps and no overlaps?","If you measured the paddle with blocks that were twice as long, would you need more blocks or fewer blocks?"],key:["6 blocks","4 blocks","The paddle. It is 2 blocks longer (6 - 4 = 2)","A gap or an overlap would make the count wrong. The blocks have to sit end to end so each one covers its own part of the length","Fewer blocks. Bigger units means it takes fewer of them to cover the same length"],desc:"measuring length as a whole number of same-size units laid end to end"}]},{id:11,title:"Camp Clock and Fair Shares",short:"Clock",parts:[{title:"Camp Clock",std:["1.MD.B.3"],n:5,dur:70,dir:"Look at each clock. Say the time out loud. Write the last one on your paper.",html:()=>`<p class="big" style="margin-top:0">The clock in the camp kitchen keeps everyone on time.</p>`,fig:()=>clockRow(),key:["Clock A: 3:00, said as three o'clock. The minute hand is on the 12.","Clock B: 7:30, said as seven thirty or half past seven. Watch for a student who says eight thirty because the hour hand has moved halfway to the 8.","Clock C: 11:00, said as eleven o'clock.","Clock D: 1:30, said as one thirty or half past one. The hour hand sits between the 1 and the 2.","Say: The canoes go out at half past four. Write that time on your paper. (4:30)"],desc:"telling and writing time to the hour and the half hour"},{title:"Fair Shares",std:["1.G.A.3"],n:5,dur:70,dir:"Look at the three shapes. Answer out loud.",fig:()=>F.row(sharesFig()),qs:["Shape A is cut into 2 equal parts. What do we call one of those parts?","Shape B is cut into 4 equal parts. What do we call one of those parts?","Think about one shape the size of Shape A. Is one half of it bigger or smaller than one fourth of it?","Shape C is cut into 2 parts. Are those parts halves? How do you know?","You want to share one round camp pancake equally with 3 friends. Into how many equal parts do you cut it, and what is each part called?"],key:["A half, or one half. Two of them make the whole circle","A fourth, or a quarter. Four of them make the whole square","Bigger. The more equal parts you cut a shape into, the smaller each part gets, so a half is bigger than a fourth of the same shape","No. The line is not down the middle, so the two parts are not the same size. Halves have to be two equal parts","4 equal parts, because there are 4 people in all. Each part is a fourth, or a quarter"],desc:"halves and fourths of circles and rectangles, and knowing that equal shares must be the same size"}]},{id:12,title:"Log Tally",short:"Chart",parts:[{std:["1.MD.C.4"],n:5,dur:75,dir:"Look at the graph. Answer out loud.",html:()=>`<p class="big" style="margin-top:0">The crew counted the logs they carried up on three mornings and made this graph.</p>`,fig:()=>F.row(F.barGraph({title:"Logs carried each morning",cats:["Monday","Tuesday","Wednesday"],vals:[7,10,5],max:10,step:1})),qs:["How many logs were carried on Tuesday?","Which morning had the fewest logs?","How many more logs on Tuesday than on Wednesday?","How many logs on Monday and Wednesday together?","How many logs were carried on all three mornings?"],key:["10","Wednesday, with 5","5 more (10 - 5 = 5)","12 (7 + 5 = 12)","22 (7 + 10 + 5 = 22)"],desc:"reading a graph with three categories and answering how many more and how many in all"}]},{id:13,title:"Camp Sign Check",short:"Signs",parts:[{title:"Sentence Spotter",std:["RF.1.1"],n:4,dur:45,dir:"Look at the sentences. Answer out loud.",html:()=>`<p class="passage" style="text-align:center">The canoe is ready. Can you carry the paddle?</p>`,qs:["How many sentences do you see? How can you tell?","Read the first word of the second sentence. What kind of letter does it start with?","What is the mark at the end of the second sentence called? What does it tell you?","Spot the mistake. Look at the words in the box. What 2 things need to be fixed?"],fig2:()=>`<div class="figure"><p class="passage" style="border:3px dashed var(--line);border-radius:16px;padding:10px 26px;margin:0">the lake is cold</p></div>`,key:["2 sentences. Each one starts with a capital letter and ends with an end mark","The word is Can. It starts with a capital, or uppercase, C","A question mark. It tells you the sentence asks something","The first word needs a capital letter, and the sentence needs a period at the end"],desc:"finding sentences by their first word, capital letter, and end mark"},{title:"Camp Fix It",std:["L.1.1"],n:6,dur:60,dir:"Listen to your teacher read each one. Say your answer out loud.",qs:["Today we hike up the trail. Last night we ____.","One tent, two ____.","Which sounds right? The otter swim at dawn. Or: The otter swims at dawn.","Join these two sentences with the word <b>and</b>: The fire is warm. The soup is hot.","Add a word that tells more about the canoe: The ____ canoe is tied to the dock.","Finish it so it tells where: The frog sits ____ the log."],key:["hiked","tents","The second one. One otter goes with the verb swims","The fire is warm, and the soup is hot","Any describing word that fits, such as red, old, wooden, or little","Any word that tells where and fits, such as on, under, by, or near"],desc:"spoken grammar items (past tense, plural nouns, subject and verb match, joining two sentences, describing words, place words)"}]},{id:14,title:"Camp Radio",short:"Listen",parts:[{title:"Listen Up",std:["SL.1.2"],n:4,dur:55,read:DUGOUT,dir:"Listen carefully. Your teacher will read about how people made canoes long ago. Then answer out loud.",html:()=>`<p class="huge" aria-hidden="true">${ic(EAR,96)}</p><p class="big" style="text-align:center">Listen.</p>`,key:["Ask: What did people make a canoe out of? (one single tree, a big straight log)","Ask: What did they do to the log? (hollowed out the middle, a little at a time, until the walls were thin and even)","Ask: What is a boat made that way called? (a dugout)","Say: Ask me one question about dugout canoes. (asks 1 question that is about what was read and starts with a question word, such as: How long did it take to make one?)"],desc:"asking and answering questions about a text read aloud"},{title:"Tell Me About It",std:["SL.1.4"],n:3,label:"checks met",dur:50,dir:"Talk for about one minute. Speak clearly.",html:()=>`<p class="big">Tell me about something you can see or hear outside early in the morning.</p><ul class="qlist" style="margin-top:14px"><li>What is it?</li><li>What does it look like? What does it sound like?</li><li>How do you feel when you see or hear it?</li></ul>`,key:["Names the thing and gives 2 or more details about it (SL.1.4)","Gives 2 or more details about what it looks like or sounds like, and they stay on this one thing (SL.1.4)","Says how it makes them feel, in at least 1 complete sentence (SL.1.4)"],desc:"describing a thing with relevant details"}]},{id:15,title:"Why Pines Stay Green",short:"Pines",parts:[{std:["RI.1.1"],n:5,dur:65,dir:"Read about pine trees out loud. Then answer out loud.",html:()=>`<div class="figure" aria-hidden="true">${ic(PINE,72)}${ic(SQUIRREL,72)}</div>${story("Why Pines Stay Green",PINES)}`,qs:["What do most trees do when the cold comes?","What are a pine tree's leaves like?","What does the waxy coat on a needle do?","How long can one needle stay on the branch?","Ask me a question about pine trees."],key:["They drop all their leaves","Thin, hard needles with a waxy coat","It keeps the water inside the needle","Two years or more","Asks a real question about pine trees, such as: How many needles does one tree have? If stuck, say: Start with what, why, or how."],desc:"asking and answering key detail questions about an informational text the student read"}]},{id:16,title:"Pack for the Lookout",short:"Pack List",parts:[{std:["W.1.8"],n:3,label:"checks met",dur:60,dir:"Look at the chart. Write 1 sentence on your paper and hold it up.",html:()=>`<p class="big">The group wants to hike up to the lookout and walk back after the sun goes down. What will they take? Use the chart.</p>`,fig:()=>packList(),key:["Finds the answer in the chart. Your help is fine: read the two columns out loud and point to the row headings","Writes a sentence drawn from the chart, such as: They will take the flashlight","The answer fits the question. It names the one item on the list that is for seeing after the sun goes down"],desc:"using a provided chart to answer a question in writing"}]},{id:17,title:"Camp Journal",short:"Write",parts:[{wk:"opinion",alt:{group:"write",key:"opinion",label:"Dock or Lookout",icon:"💬",hint:"Tell what you think and why"},std:["W.1.1"],n:4,label:"checks met",dur:150,dir:WDIR,html:()=>`<p class="big">Would you rather spend the afternoon swimming at the dock, or hiking up to the lookout? Write what you think and tell why.</p><div class="figure">${F.pic("swim","swimming at the dock","3.6rem")}${F.pic(MOUNTAIN,"hiking to the lookout","3.6rem")}</div>${TWO}`,key:["Names the topic: swimming at the dock or hiking to the lookout (W.1.1)","States an opinion, which one the student would pick (W.1.1)","Gives at least one reason for the opinion, such as it is cooler or you can see further (W.1.1)","Gives some sense of closure, such as: That is why I would pick it (W.1.1)"],desc:"an opinion piece about how to spend an afternoon at camp"},{wk:"facts",alt:{group:"write",key:"facts",label:"Camp Facts",icon:"📖",hint:"Tell a reader what it is"},std:["W.1.2"],n:4,label:"checks met",dur:150,dir:WDIR,html:()=>`<p class="big">Pick one: a canoe, a campfire, or a pine tree. Write what it is and tell a reader two true things about it.</p><div class="figure">${F.pic(CANOE,"a canoe","3.4rem")}${F.pic(FIRE,"a campfire","3.4rem")}${F.pic(PINE,"a pine tree","3.4rem")}</div>${TWO}`,key:["Names the topic: the canoe, the campfire, or the pine tree (W.1.2)","Gives at least one true fact about it (W.1.2)","Gives a second true fact or detail about it (W.1.2)","Gives some sense of closure, such as a last sentence that wraps it up (W.1.2)"],desc:"an informative piece about one thing at camp"},{wk:"story",alt:{group:"write",key:"story",label:"A Day Outside",icon:"✏",hint:"Tell two things that happened, in order"},std:["W.1.3"],n:4,label:"checks met",dur:150,dir:WDIR,html:()=>`<p class="big">Write about a day you spent outside. Tell two things that happened, in order. Use the words first and then. End by telling how it felt.</p><div class="figure">${F.pic(SUN,"the day","3.4rem")}${F.pic(BOOT,"where you went","3.4rem")}${F.pic(SOUP,"how it felt","3.4rem")}</div>${TWO}`,key:["Tells about two or more things that happened, in an order that makes sense (W.1.3)","Includes some detail about what happened, not just a list (W.1.3)","Uses a time word such as first, then, next, or after that to signal the order (W.1.3)","Ends with a sense of closure, such as how it felt or what happened last (W.1.3)"],desc:"a narrative about a day the student spent outside, told in order"}]},{id:18,title:"Copy a Crab Claw",short:"Copy a Part",parts:[{std:["1-LS1-1"],n:3,dur:90,dir:"Look at the pictures. Answer the first out loud. Draw the second on your paper and hold it up.",desc:"naming the job an animal body part does, then designing a tool that copies it to solve a human problem",html:()=>`<p class="big">A crab has a claw. It is made of two curved halves. They close on each other. It can pick up something small. The thing may be slippery. It can hold on to it. It does that without crushing it.</p>
     <div class="figure">${ic("crab",104)}${ic("shell",88)}</div>
     <p class="big">The cook is at the camp kitchen. She tries to lift hot corn. She uses two forks. She lifts it out of the pot. She keeps dropping it.</p>`,qs:["How do two curved halves closing on each other hold something better than one flat spoon does?","Draw a tool for the cook that copies the crab's claw.","Tell me which animal part you copied and how your tool holds the corn without dropping it."],key:["They close from both sides at once, so the thing is held between them and cannot slide out. Any answer about gripping from both sides counts.","Any two sided gripping tool: tongs, pincers, two sticks joined at one end, a clamp, a clip. One flat spoon is partial, so ask how many sides a claw grips from.","Needs both halves: names the two sided curved claw as the part copied, and says squeezing from both sides holds the corn instead of letting it roll off."]}]},{id:19,title:"Duck and Ducklings",short:"Parents",parts:[{std:["1-LS1-2"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"finding a pattern in what a parent animal does and what the young do in answer, and saying how it helps the young",read:"Each morning a duck comes out of the reeds at the edge of the lake with seven ducklings behind her. She goes first, and they follow in one line so close that each one is almost touching the one in front. She keeps up a soft quacking while they walk. If she stops, every duckling stops. When she steps into the water they go in one after another, in the same order they walked in, and they stay inside the little curve of water she makes as she swims.",qs:["What do the ducklings do every single time the duck stops walking?","In what order do the ducklings go into the water?","How does following in one line right behind the parent help the ducklings in the water?"],key:["They stop too. Every single time is what makes it a pattern.","The same order they walked in, one after another behind her.","They stay together where she can keep track of them, they stay in the smoother water she makes, and none of them gets left behind. Any sensible answer counts."]},{std:["1-LS3-1"],n:3,dur:75,dir:"Look at the pictures. Answer out loud.",desc:"making observations that young plants and animals are like their parents but not exactly like them",html:()=>`<p class="big">Two sunflowers grown from seed off the same parent plant. A young turtle and the turtle that is its parent.</p>
     <div class="figure">${ic("sunflower",84)}${ic("sunflower",112)}</div>
     <div class="figure">${ic("turtle",84)}${ic("turtle",112)}</div>`,qs:["Both sunflowers came from the same parent plant, but one grew much taller. Are they both still sunflowers? Say why.","Name one way both sunflowers are like the plant they came from.","The young turtle has the same shell pattern and the same four legs as its parent, but its shell is much softer. Name one more way a young turtle is not exactly like its parent."],key:["Yes. Plants from the same parent are like it and like each other, but not exactly the same, and height is one of the things that can differ.","Both have a tall stem, big leaves, and a round yellow flower head. Any likeness counts.","It is much smaller, its colors may be brighter or paler, it cannot swim as far or as fast. Any sensible difference counts."]}]},{id:20,title:"Sunset at the Lake",short:"Sky Patterns",parts:[{std:["1-ESS1-1"],n:4,dur:90,dir:"Look at the log. Answer out loud.",desc:"finding a pattern in a log of sky observations and using it to predict what comes next",html:()=>`<p class="big">The camp keeper wrote down the time the sun went behind the far shore, once a week for four weeks in late summer.</p>
     <table class="bigTable"><tr><th>Week</th><th>Time the sun went down</th></tr>
     <tr><td>first week</td><td>8:41</td></tr><tr><td>second week</td><td>8:33</td></tr>
     <tr><td>third week</td><td>8:25</td></tr><tr><td>fourth week</td><td>8:17</td></tr></table>
     <div class="figure">${ic("sun",84)}${ic("wave",84)}${ic("pine",84)}</div>`,qs:["Is the sun going down earlier or later as the weeks go by?","How many minutes earlier does it go down each week?","What time do you predict the sun will go down in the fifth week, and how do you know?","Does the sun go down behind the far shore because somebody moved it there, or because that is the pattern it follows every day?"],key:["earlier each week","8 minutes earlier each week","8:09. The times go down by 8 minutes each week, and a pattern that repeats lets you predict what comes next.","Because that is the pattern it follows. The sun comes up on one side and goes down on the other every single day, and nobody moves it."]},{std:["1-ESS1-2"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"relating the number of hours of daylight to the time of year from observations made across a year",html:()=>`<p class="big">Hours of daylight at the lake, counted on one day in each of four months.</p>
     <table class="bigTable"><tr><th>Month</th><th>Hours of daylight</th></tr>
     <tr><td>June</td><td>15</td></tr><tr><td>August</td><td>13</td></tr>
     <tr><td>October</td><td>11</td></tr><tr><td>December</td><td>9</td></tr></table>`,qs:["Which month on the chart had the longest daylight?","What is happening to the hours of daylight as the months go from June to December?","Swimming is only allowed in daylight. Using the chart, say whether there is more time to swim in a June day or an October day, and by how many hours."],key:["June, 15 hours","They are going down, two fewer hours each time.","June, by 4 hours. June has 15 hours of daylight and October has 11."]}]},{id:21,title:"Sound at the Water",short:"Sound",parts:[{std:["1-PS4-1"],n:4,dur:90,dir:"If you have an empty bottle, try the first part. Either way, answer out loud.",desc:"planning an investigation showing that a shaking material makes sound and that a sound can make a material shake",html:()=>`<p class="big">Blow hard across the open top of an empty bottle until it hoots. Then put your hand flat on your own throat and hum a long low note.</p>
     <div class="figure">${ic("milk",96)}${ic("drop",96)}</div>
     <p class="big">Now stand a cup of water on the picnic table and drum hard on the table beside it.</p>`,qs:["When the bottle hoots, what is shaking to make that sound: the glass, or the air inside it?","What do you feel under your hand while you hum, and what happens to it when you stop?","What happens to the top of the water in the cup while you drum on the table?","Nothing touched the water. Say what made it move."],key:["The air inside it. Blowing across the top sets the air shaking, and the shaking air makes the hoot.","A buzzing or a tickle. It stops the moment the humming stops, which shows the shaking and the sound go together.","Little ripples run across it, or it jumps.","The drumming shook the table, the shaking table shook the cup, and the shaking cup moved the water. A sound and the shaking that makes it can pass from one thing to another."]}]},{id:22,title:"The Dark Boathouse",short:"Light",parts:[{std:["1-PS4-2"],n:3,dur:75,dir:"Answer out loud.",desc:"accounting for why an object in darkness can be seen only when light shines on it",html:()=>`<p class="big">The boathouse has no window. When both doors are pulled shut, it is completely dark inside.</p>
     <div class="figure">${ic("beachBall",96)}${ic("torch",96)}</div>`,qs:["A big striped beach ball is sitting in the middle of the dark boathouse. Can you see it? Say why or why not.","What would someone have to do before the ball could be seen in there?","A white towel hangs on a hook in the same dark boathouse. Is the white towel easier to see than the ball when there is no light? Say why."],key:["No. No light gets into the boathouse, and a thing can only be seen when light shines on it and comes back to your eyes.","Light has to reach it: a flashlight, a lamp, or a door opened so daylight comes in.","No. With no light at all nothing can be seen, white or striped. White only looks brighter once there is light for it to bounce back."]},{std:["1-PS4-3"],n:4,dur:90,dir:"Look at the test results. Answer out loud.",desc:"using test results to tell what happens when different materials are put in the path of a beam of light",html:()=>`<p class="big">One flashlight beam was pointed at four things in the boathouse and what it did was written down.</p>
     <table class="bigTable"><tr><th>What was put in the beam</th><th>What the beam did</th></tr>
     <tr><td>a jar of clear lake water</td><td>went through, a little bent</td></tr>
     <tr><td>the cloth of a beach umbrella</td><td>a soft colored light came through</td></tr>
     <tr><td>a thick dock board</td><td>stopped, and made a dark shadow</td></tr>
     <tr><td>a shiny steel cup</td><td>bounced off sideways</td></tr></table>`,qs:["Which thing stopped the beam altogether?","Which thing let a soft colored light through?","Sitting under a beach umbrella the light on your arms looks the color of the umbrella. Use the chart to explain why.","Name the two things on the chart that would leave a darker patch behind them, and say what each one did with the light."],key:["the thick dock board","the cloth of the beach umbrella","Some light comes through the cloth and the cloth tints it as it passes, so what lands on your arms is softened and colored.","The dock board and the steel cup. The board stopped the light, and the cup sent it off sideways. Both leave less light behind them, for different reasons."]}]},{id:23,title:"Dock to Raft",short:"Signals",parts:[{std:["1-PS4-4"],n:3,dur:90,dir:"Draw your answer on your paper. Then answer out loud.",desc:"designing a device that uses light or sound to send a message over a distance too far to shout",html:()=>`<p class="big">The swimming raft is far out. It sits on the lake. A shout comes from the dock. It is swallowed up. That happens before it gets there. Waving an arm is easy to miss.</p>
     <div class="figure">${ic("wave",88)}${ic("megaphone",88)}${ic("flag",88)}</div>`,qs:["Draw a device on the dock that tells the swimmers on the raft that it is time to come in. It has to use light or sound.","Point to your drawing and tell me if it signals with light or with sound.","The swimmers' heads are under the water half the time. Which travels better to somebody who is looking down, a light or a sound? Say which you would choose and why."],key:["Any device that carries light or sound out over the water: a whistle, a horn, a bell, a bright lamp, a lamp flashed on and off.","Names it and says which one it uses.","A sound, because you do not have to be looking at it to notice it. A student who picks a very bright light and explains that it can be seen even underwater is reasoning well, so take the reasoning."]}]},{id:24,title:"Fix the Blowing Cups",short:"Fix It",parts:[{std:["K-2-ETS1-1"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"naming a problem people want to change, asking a question about it, and saying what to observe first",read:"Lunch at the camp is eaten at the long picnic table beside the water. Light paper cups are handed out empty and set down while the food comes round. Nearly every day the breeze off the lake takes several of them off the table and the campers have to go and pick them up out of the grass.",qs:["What is the problem the camp wants to change?","Ask me one question that would help you understand the problem better.","What would you watch at one lunch, before you built a thing?"],key:["The breeze blows the empty paper cups off the picnic table.","Any real question: how strong is the breeze, which way does it come from, are the cups empty or full, how heavy is a cup, how many blow off. A statement is not a question, so ask once more.","Any real observation: count how many blow off at one lunch, watch whether full cups blow off too, see which end of the table loses the most, note which way the wind comes from."]},{std:["K-2-ETS1-2"],n:3,dur:90,dir:"Draw your answer on your paper and hold it up. Then answer out loud.",desc:"making a simple drawing of a fix and explaining how the shape of the object makes it work",html:()=>`<p class="big">Draw something that keeps the empty cups on the table in the breeze.</p>
     <div class="figure">${ic("box",88)}${ic("ruler",88)}${ic("shell",88)}</div>`,qs:["Draw your fix on the picnic table.","Point to the part that holds the cup and tell me its shape.","Tell me why that shape works better than asking everyone to hold their own cup."],key:["Any real fix: a tray with round holes the cups drop into, a rack, a lid that clips on, a weight dropped in each cup, a rim round the edge of the table, a box the cups sit in until they are filled.","Names a shape: a round hole the cup sits in, a deep box, a rim along the edge, a clip.","Because the shape holds every cup every time with nobody thinking about it. Holding your own cup only works while everyone remembers to."]}]},{id:25,title:"Which Holder Worked",short:"Test Data",parts:[{std:["K-2-ETS1-3"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"comparing the data from tests of two objects built to solve the same problem",html:()=>`<p class="big">Two cup holders were tested at the same lunch, ten cups in each, on the same table.</p>
     <table class="bigTable"><tr><th>Holder</th><th>Cups that blew off, out of 10</th></tr>
     <tr><td>a tray with round holes</td><td>0</td></tr>
     <tr><td>a flat mat under the cups</td><td>7</td></tr></table>`,qs:["Which of the two kept more cups on the table?","Say how you can tell from the counts in the chart.","Both holders were tested at the same lunch on the same table. Why does that make the test fair?"],key:["the tray with round holes","Not one cup out of 10 blew off the tray, and 7 out of 10 blew off the flat mat. The numbers have to be in the answer.","Because the wind was the same for both. If one had been tested on a still day you would not know whether the holder or the weather made the difference."]}]},{id:26,title:"The Public Lake",short:"Rights",parts:[{std:["HSS-1.1"],n:4,dur:90,dir:"Listen while your teacher reads. Then answer out loud.",desc:"telling a right from a responsibility and explaining why a place everybody owns has rules",read:"The lake and the beach beside it belong to the whole county, so anybody may go there. There are three signs at the gate. Swim only where a guard is watching. Carry out whatever you carried in. Dogs on a lead past the picnic tables. Nobody owns the beach, so nobody is there to clean up after anybody else.",qs:["Anybody in the county may use the beach. Is that a right or a responsibility?","Carrying out whatever you carried in is something you do. Is that a right or a responsibility?","The sign says to swim only where a guard is watching. Who is that rule for?","Nobody owns the beach, so nobody is paid to tidy it. What does that mean for the people who use it?"],key:["a right","a responsibility","For the swimmer, and for everybody else too, because a guard can only watch one place at a time. Any answer about keeping people safe counts.","They have to look after it themselves. A place that belongs to everybody is only kept nice if each person takes care of their own part."]}]},{id:27,title:"The Lake Map",short:"Map Grid",parts:[{std:["HSS-1.2"],n:6,dur:110,dir:"Look at the map grid. Answer out loud.",desc:"giving an exact grid location, describing a relative location, telling a physical feature from a built one, and telling how the place and its weather change the way people live",html:()=>`<p class="big">A map of the camp and the lake, drawn on a grid.</p>
     <table class="bigTable"><tr><th></th><th>1</th><th>2</th><th>3</th></tr>
     <tr><th>A</th><td>${ic("pine",56)}</td><td>${ic("tent",56)}</td><td>${ic("cabin",56)}</td></tr>
     <tr><th>B</th><td></td><td>${ic("bridge",56)}</td><td></td></tr>
     <tr><th>C</th><td>${ic("wave",56)}</td><td>${ic("wave",56)}</td><td>${ic("canoe",56)}</td></tr></table>
     <p class="big">${ic("pine",48)} the pine wood &nbsp; ${ic("tent",48)} the tents &nbsp; ${ic("cabin",48)} the lodge &nbsp; ${ic("bridge",48)} the plank walk &nbsp; ${ic("wave",48)} the lake &nbsp; ${ic("canoe",48)} the boat dock</p>
     <p class="big">The top of this map is north. The bottom is south, the right is east, and the left is west.</p>
     <p class="big">The camp sits right on the lake, and the summers here are warm.</p>`,qs:["Find the lodge. Give its exact spot on the grid, the letter and the number.","Where is the boat dock compared to the lodge? Use north, south, east or west.","Which two things on this map did nobody have to build?","This camp is right on a lake. Name one food people here could get from the lake.","The summers here are warm. Name one kind of shelter that works well in warm weather.","Name one thing people do here for fun because the lake is right there."],key:["A3. Both parts are needed. (HSS-1.2)","South of the lodge, in the same column. South alone is a full answer. (HSS-1.2)","The pine wood and the lake. (HSS-1.2)","Fish. Any food that really comes out of a lake counts. (HSS-1.2)","A tent, a cabin with the windows open, or a shelter with just a roof for shade. (HSS-1.2)","Swimming, canoeing or boating from the dock, or fishing. (HSS-1.2)"]},{std:["HSS-1.5"],n:3,dur:75,dir:"Answer out loud.",desc:"naming built features of a familiar place and recognizing that people in one place come from many different places",html:()=>`<p class="big">The campers came this week. They came from eleven different towns. They came from three different states. On the first night they taught. Each one taught the others. Each one taught one game from home. No two games were the same.</p>
     <p class="big">On the second night they told stories. They did that instead. A group of people tell old stories. They hand them down. Those stories are called folklore. Some campers also talked about more. They talked about what their families believe. They talked about ceremonies their families hold. One is such a day. A new baby gets a naming. One is a meal. The whole family comes home for it.</p>
     <div class="figure">${ic("tent",88)}${ic("soccerBall",88)}${ic("globe",88)}</div>`,qs:["Do people who spend a week in the same place all come from the same town? Say how you know from the story.","Name three things people built at a camp or a park you have been to, and say what one of them is for.","The old stories a group of people hand down are called folklore. Name one way two families might be different in what they believe, in a ceremony they hold, or in the stories they tell, and name one thing those two families would still share."],key:["No. They came from eleven towns and three states.","Any three built things with a use for one: a dock for boats, a cabin to sleep in, a path to walk on, a bench to sit on, a shelter for shade.","Needs both halves. A difference in beliefs, a ceremony or folklore: one family prays and another does not, one holds a naming day for a new baby, one has a big family meal everybody comes home for, one tells stories from the country their grandparents came from. A thing they still share: they live in the same town, their children are at the same school, they use the same park and the same shops, they both want their children to do well. (HSS-1.5)"]}]},{id:28,title:"Symbols, Then and Now",short:"Symbols",parts:[{std:["HSS-1.3"],n:3,dur:75,dir:"Answer out loud.",desc:"naming a national day and the traditions that go with it, and telling what the day is for",html:()=>`<p class="big">The fourth day of July is special. The country marks a day then. It is the day it began. Towns put flags along the streets. People watch fireworks after dark. Bands play in the park.</p>
     <div class="figure">${ic("flag",96)}${ic("firework",96)}</div>`,qs:["What do towns put along the streets on Independence Day?","Is a day like that a day we remember something together, or only a day off work and school?","Fireworks, flags and a band in the park happen in town after town, year after year. What do you call something people keep doing like that?"],key:["Flags.","A day we remember something together. The country is marking the day it began. If the student says both, that is a good answer, as long as the remembering is in it.","A tradition. Accept a custom. If the student cannot name it, ask what they call the things their own family does every year."]},{std:["HSS-1.4"],n:4,dur:90,dir:"Look at the chart. Answer out loud.",desc:"comparing everyday life long ago with life today and telling what changed from what stayed the same",html:()=>`<p class="big">Keeping cool on a hot day.</p>
     <table class="bigTable"><tr><th></th><th>Long ago</th><th>Today</th></tr>
     <tr><td>inside the house</td><td>a fan waved by hand, windows wide open</td><td>a machine that cools the whole room</td></tr>
     <tr><td>a cold drink</td><td>water from a deep cool cellar</td><td>ice from the freezer</td></tr>
     <tr><td>the best free way</td><td>sit in the shade of a tree</td><td>sit in the shade of a tree</td></tr>
     <tr><td>the town summer fair</td><td>a parade down main street, a band in the park, races on the grass</td><td>a parade down main street, a band in the park, races on the grass</td></tr></table>
     <div class="figure">${ic("sun",88)}${ic("tree",88)}</div>`,qs:["Long ago, how did people make the inside of a house cooler?","How is a room cooled today?","Name one thing from the chart that people stopped doing the old way.","Towns have held a summer fair for a very long time. Name two things people do at a fair like that, and say whether a fair is something that changed a lot or something that stayed much the same."],key:["A fan waved by hand, and the windows opened wide.","A machine that cools the whole room.","How the inside of a house was cooled changed, or where a cold drink came from changed. Either counts.","Any two from the fair row: a parade down main street, a band in the park, races on the grass. A fair is something that stayed much the same, which is why its row reads the same on both sides. A festival like this is one of the things the standard asks you to compare. (HSS-1.4)"]}]}];const LEVELUPS={2:{id:"L2",lv:true,title:"Level Up: Longer Words",std:["RF.2.3"],needs:["RF.1.3"],n:3,dir:"Read each word out loud.",html:()=>`<div style="text-align:center">${["downstream","unpacked","tallest"].map(w=>`<p class="huge" style="font-size:clamp(2.6rem,9vw,5rem);margin:14px 0">${w}</p>`).join("")}</div>`,key:["downstream (two syllables, compound word, ea team in the second part)","unpacked (prefix un-, and the -ed ending said as /t/)","tallest (suffix -est)"]},4:{id:"L4",lv:true,title:"Level Up: The Trail Crew",std:["RF.2.4"],needs:["RF.1.4"],n:68,label:"words read correctly",dir:"Read this harder story out loud in your best reading voice.",html:()=>`<p class="passage">${CREW}</p>`,key:["68 words. Mark each word read wrong or skipped. A word the student fixes alone counts as correct.","Note pace and expression. A grade 2 reader should group the words into phrases, not read one word at a time.","Quick check after reading: Why does the crew lay flat stones? (so a walker can step across the wet spot without sinking)"]},6:{id:"L6",lv:true,title:"Level Up: Two-Step Problem",std:["2.OA.A.1"],needs:["1.OA.A.1"],n:1,dir:"Solve on your paper. Tell your teacher the answer.",html:()=>`<p class="big">The camp had 38 logs on the rack. A truck brought 25 more. Then the camp used 19 of them in the fire ring. How many logs are still on the rack?</p>`,key:["44 logs (38 + 25 = 63, then 63 - 19 = 44)"]},7:{id:"L7",lv:true,title:"Level Up: Why and How",std:["RL.2.1"],needs:["RL.1.1"],n:2,dir:"Answer out loud. Use the story.",html:()=>`<p class="passage" style="font-size:1.5rem">${PADDLE}</p><ol class="qlist"><li>Why could Teo not use the paddle at first?</li><li>How did the problem get fixed?</li></ol>`,key:["The handle was too long for him to hold with both hands","Luz held the paddle against him and marked the spot with a pencil, and the camp leader sawed the end off at the mark"]},9:{id:"L9",lv:true,title:"Level Up: Add It Both Ways",std:["2.NBT.B.5"],needs:["1.NBT.C.4"],n:3,dir:"Solve each one on your paper. Show your work and hold it up.",html:()=>`<ol class="qlist"><li>48 + 35</li><li>72 - 26</li><li>57 + 28</li></ol>`,key:["83 (48 + 35 = 83)","46 (72 - 26 = 46)","85 (57 + 28 = 85)"]}};const PASSAGE_STD=["RL.1.1","RI.1.1","RL.2.1","1-LS1-1","1-LS1-2","1-LS3-1","1-ESS1-1","1-ESS1-2","1-PS4-1","1-PS4-2","1-PS4-3","1-PS4-4","K-2-ETS1-1","K-2-ETS1-2","K-2-ETS1-3","HSS-1.1","HSS-1.2","HSS-1.3","HSS-1.4","HSS-1.5"];let nlOn={},tfOn={},c120On={};function nlHtml(){const marks=Object.keys(nlOn).filter(k=>nlOn[k]).map(Number);return F.numberLine({min:0,max:20,step:1,labelEvery:1,width:680,marks,clickable:true,fluid:true})+`<p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){return`<div class="tf-wrap">`+[0,1].map(f=>{let c=`<div class="tf">`;for(let i=0;i<10;i++){const k=f*10+i;c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`}return c+"</div>"}).join("")+`</div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear.</p>`}function c120Html(){let h=`<div class="tool-scroll"><table class="c120">`;for(let r=0;r<12;r++){h+="<tr>";for(let c=1;c<=10;c++){const n=r*10+c;h+=`<td data-n="${n}" class="${c120On[n]?"on":""}">${n}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to mark it. Click it again to clear.</p>`}const STARTERS={opinion:["I would pick ____.","One reason is ____.","It would be ____.","That is why I would pick it."],facts:["A ____ is ____.","One thing about it is ____.","It can also ____."],story:["One day, ____.","First, ____.","Then, ____.","It felt ____."]};const SENTSET={"W.1.1":"opinion","W.1.2":"facts","W.1.3":"story","W.1.8":"facts"};const SENTLAB={opinion:"If you are writing what you think:",facts:"If you are writing facts:",story:"If you are telling a story:"};function sentHtml(st){const parts=st&&st.parts&&st.parts.length?st.parts:st?[st]:[];const sets=[];parts.forEach(p=>(p.std||[]).forEach(c=>{const k=SENTSET[c];if(k&&STARTERS[k]&&sets.indexOf(k)<0)sets.push(k)}));if(!sets.length){const k=parts[0]&&parts[0].wk;sets.push(STARTERS[k]?k:"opinion")}return sets.map(k=>(sets.length>1?`<p class="small">${SENTLAB[k]}</p>`:"")+`<ul class="starters">${STARTERS[k].map(x=>`<li>${x}</li>`).join("")}</ul>`).join("")}let tpsBlk=[0,0];function tpsBlkHtml(){return`<div class="blk-row"><button class="chip" data-tb="0" data-td="1">Add a ten</button><button class="chip" data-tb="0" data-td="-1">Take a ten</button><button class="chip" data-tb="1" data-td="1">Add a one</button><button class="chip" data-tb="1" data-td="-1">Take a one</button><button class="chip" data-tb="x">Clear</button></div><div class="tool-scroll" style="text-align:center">${tpsBlk[0]+tpsBlk[1]?F.tens(tpsBlk[0],tpsBlk[1]):`<p class="small">No blocks yet.</p>`}</div><p class="small">${tpsBlk[0]} tens and ${tpsBlk[1]} ones on the mat.</p>`}function tpsBlkBind(b,r){b.querySelectorAll("[data-tb]").forEach(x=>x.onclick=()=>{if(x.dataset.tb==="x")tpsBlk=[0,0];else{const i=+x.dataset.tb;tpsBlk[i]=Math.max(0,Math.min(i?19:9,tpsBlk[i]+ +x.dataset.td))}r()})}F.clockLab=(h,m)=>{const cx=190,cy=190,R=150,pad=n=>String(n).padStart(2,"0");let s=`<svg viewBox="0 0 380 380" width="360" style="max-width:100%;height:auto" role="img" aria-label="Clock face with the hour hand and the minute hand labeled, showing ${h}:${pad(m)}">`;s+=`<circle cx="${cx}" cy="${cy}" r="${R+8}" fill="#F3DCC4" stroke="var(--fig-ink)" stroke-width="4"/><circle cx="${cx}" cy="${cy}" r="${R}" fill="var(--surface)" stroke="var(--fig-ink)" stroke-width="3"/>`;for(let i=0;i<60;i++){const a=i*Math.PI/30,l=i%5?6:13;s+=`<line x1="${cx+Math.sin(a)*(R-3)}" y1="${cy-Math.cos(a)*(R-3)}" x2="${cx+Math.sin(a)*(R-3-l)}" y2="${cy-Math.cos(a)*(R-3-l)}" stroke="var(--ink)" stroke-width="${i%5?1.3:2.6}"/>`}for(let i=1;i<=12;i++){const a=i*Math.PI/6;s+=`<text x="${cx+Math.sin(a)*108}" y="${cy-Math.cos(a)*108}" font-size="30" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)" text-anchor="middle" dominant-baseline="central">${i}</text>`}for(let i=0;i<12;i++){const a=i*Math.PI/6;s+=`<text x="${cx+Math.sin(a)*(R+23)}" y="${cy-Math.cos(a)*(R+23)}" font-size="16" font-family="Andika,sans-serif" font-weight="700" fill="var(--sea)" text-anchor="middle" dominant-baseline="central">${i*5}</text>`}const ha=(h%12+m/60)*Math.PI/6,ma=m*Math.PI/30,hl=66,ml=90;s+=`<line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ha)*hl}" y2="${cy-Math.cos(ha)*hl}" stroke="var(--ink)" stroke-width="11" stroke-linecap="round"/><line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ma)*ml}" y2="${cy-Math.cos(ma)*ml}" stroke="var(--sea)" stroke-width="6" stroke-linecap="round"/><circle cx="${cx}" cy="${cy}" r="8" fill="var(--ink)"/>`;const tag=(ang,r,txt,col)=>{let d=ang*180/Math.PI-90;if(d>90||d<-90)d+=180;const x=cx+Math.sin(ang)*r,y=cy-Math.cos(ang)*r;return`<text transform="translate(${x.toFixed(1)} ${y.toFixed(1)}) rotate(${d.toFixed(1)})" y="-12" font-size="14" font-weight="700" font-family="Andika,sans-serif" fill="${col}" stroke="var(--surface)" stroke-width="3" paint-order="stroke" text-anchor="middle" dominant-baseline="central">${txt}</text>`};s+=tag(ha,38,"hour hand","var(--ink)")+tag(ma,51,"minute hand","var(--sea)");return s+`</svg>`};function tpsClockHtml(){return F.row([F.clockLab(3,0),"3:00, three o'clock"],[F.clockLab(7,30),"7:30, half past seven"])+`<ul class="frames"><li><b>Short hand = hours.</b> Read the big numbers, 1 to 12.</li><li><b>Long hand = minutes.</b> Read the small numbers around the edge. They count by 5s.</li></ul>`+F.table(["Where the long hand points","Minutes","How to write it and say it"],[["straight up at the 12","0 minutes","3:00, three o'clock"],["straight down at the 6","30 minutes","7:30, seven thirty or half past seven"]])+`<ul class="frames"><li>The short hand is the hour. The long hand is the minutes.</li><li>At half past, the short hand sits between two numbers. Say the smaller number.</li></ul>`}function tpsRulerHtml(){return F.row(F.ruler({length:6,px:70,parts:1,unit:"in",item:4,itemLabel:"pencil"}))+F.table(["Rule","Why it matters"],[["Start at the 0 end","the first unit has to begin where the object begins"],["The units touch, with no gaps","a gap makes the count too small"],["The units do not overlap","an overlap makes the count too big"],["Every unit is the same size","units of different sizes cannot be counted together"]])+`<p class="small">Count the spaces between the marks, not the marks themselves. The pencil above ends at the 4, so it is 4 units long.</p>`}function tpsLetterHtml(){return F.table(["Pattern","What it does","Words"],[["sh, ch, th, wh, ck","two letters, one sound","shop, chin, that, when, duck"],["bl, fl, st, sw, cr","two sounds said close together","flag, stop, swim, crab"],["a_e, i_e, o_e, u_e","the e at the end makes the vowel say its name","cave, bike, note, cube"],["ai, ay, ea, ee, oa, ow","a vowel team: two letters, one vowel sound","rain, day, seal, deep, boat, snow"],["ar, er, ir, or, ur","the r changes the vowel","barn, her, bird, corn, fur"],["-s, -ed, -ing","an ending added to a word","jumps, jumped, jumping"]])+`<ul class="frames"><li>Say each sound, then blend them together. /f/ /l/ /a/ /g/ is flag.</li><li>A long vowel says its name. A short vowel does not.</li><li>Clap the parts: snow-flake is two parts.</li></ul>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","who it is about and where they are","First, ____."],["2. Next","what happened in the middle","Next, ____."],["3. Last","how it ended and how you felt","Last, ____."]])+`<ul class="frames"><li>Keep the parts in the order they happened.</li><li>Use the names from the story, not he or she on its own.</li></ul>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={nl:{name:"Number line to 20",std:["1.MD.A.2","1.MD.B.3","1.MD.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.MD.A.1"],html:nlHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{nlOn[x.dataset.n]=!nlOn[x.dataset.n];r()})},tf:{name:"Ten frames",std:["1.NBT.B.2","1.NBT.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.NBT.A.1"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},chart:{name:"120 chart",std:["1.NBT.A.1","1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","1.OA.C.5","2.NBT.A.1","2.NBT.B.5","2.OA.A.1"],html:c120Html,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{c120On[x.dataset.n]=!c120On[x.dataset.n];r()})},sent:{name:"Sentence starters",std:["W.1.1","W.1.2","W.1.3","W.1.8"],html:sentHtml},blocks:{name:"Tens and ones blocks",std:["1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","2.NBT.B.5","2.OA.A.1"],html:tpsBlkHtml,bind:tpsBlkBind},clock:{name:"Clock face card",std:["1.MD.B.3","2.MD.C.7"],html:tpsClockHtml},ruler:{name:"Inch ruler card",std:["1.MD.A.2","2.MD.A.1"],html:tpsRulerHtml},letters:{name:"Letter and sound card",std:["RF.1.2","RF.1.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["RL.1.1","SL.1.4","W.1.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","L.1.1","RI.1.1","RL.1.1","SL.1.2"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.1.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"nl",std:["1.OA.C.5"],msg:"1.OA.C.5 is about counting on and back. With the number line, this stop shows the student can do it with a visual, not in their head."},{t:"nl",std:["1.OA.B.3"],msg:"1.OA.B.3 is about using number tricks (turn-around facts, making ten). If the student counts every hop on the number line, the stop shows counting, not the strategy."},{t:"chart",std:["1.NBT.A.1"],msg:"The 120 chart shows the numerals, so counting, reading, and writing numbers with it open is supported, not independent."},{t:"chart",std:["1.NBT.C.4","1.NBT.C.6"],msg:"On the 120 chart a student can hop down a column to add or take away a ten. Note whether the answer came from the chart or from knowing the tens."},{t:"tf",std:["1.NBT.B.2"],msg:"Ten frames show the bundles of ten for the student. Note it if the tens and ones were read off the frames rather than said from the number."},{t:"sent",msg:"Sentence starters supply the opening, the time words, and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"scribe",std:["W.1.1","W.1.2","W.1.3","W.1.8"],msg:"If an adult wrote the words for the student, note it. The writing checks still count, but the printing does not."},{t:"clock",std:["1.MD.B.3","2.MD.C.7"],msg:"The clock card names which hand is the hour and what each long hand position is worth, so a time read with it open is supported, not independent."},{t:"ruler",std:["1.MD.A.2","2.MD.A.1"],msg:"The ruler card shows the units already laid end to end from 0 and states the no gaps rule, so count a length found with it open as supported, not independent."},{t:"letters",std:["RF.1.3"],msg:"The letter and sound card lists the patterns and an example word for each, so a word sounded out with it open is supported, not independent."},{t:"letters",std:["RF.1.2"],msg:"RF.1.2 is listening only. If the card was open, note that the student had the blending and long vowel rules in front of them."},{t:"retell",std:["RL.1.1","SL.1.4","W.1.3"],msg:"The card gives the order words first, next and last, so count the order as supported and rate the details the student supplies."},{t:"qwords",std:["RL.1.1","RI.1.1","SL.1.2","L.1.1","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.1.4"],msg:"A timed read with the reading window open is not a clean fluency baseline. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
